void main()=>runApp(const CRMApp());
class CRMApp extends StatelessWidget { const CRMApp({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Εργασίες Πελατών',theme:ThemeData(colorSchemeSeed:Colors.blue,useMaterial3:true),home:const ClientListScreen()); }
String newId()=>DateTime.now().microsecondsSinceEpoch.toString();
String dateText(DateTime d)=>'${d.day.toString().padLeft(2,'0')}/${d.month.toString().padLeft(2,'0')}/${d.year}';
String timeText(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
String norm(String s){const a='άέήίόύώϊΐϋΰΆΈΉΊΌΎΏ';const b='αεηιουωιιυυΑΕΗΙΟΥΩ';for(var i=0;i<a.length&&i<b.length;i++){s=s.replaceAll(a[i],b[i]);}return s.toLowerCase().trim();}
String cell(List<Data?> r,int i)=>i>=0&&i<r.length?(r[i]?.value?.toString().trim()??''):'';

class Interaction {
 final String id,type,notes; final DateTime date;
 const Interaction({required this.id,required this.type,required this.date,required this.notes});
 Map<String,dynamic> toJson()=>{'id':id,'type':type,'date':date.toIso8601String(),'notes':notes};
 factory Interaction.fromJson(Map<String,dynamic> j)=>Interaction(id:'${j['id']??newId()}',type:'${j['type']??'Τηλεφώνημα'}',date:DateTime.tryParse('${j['date']??''}')??DateTime.now(),notes:'${j['notes']??''}');
}
class Client {
 final String id,fullName,phone,address,customerCode; final DateTime createdDate; final List<Interaction> interactions;
 Client({required this.id,required this.fullName,required this.phone,required this.address,required this.createdDate,this.customerCode='',List<Interaction>? interactions}):interactions=interactions??[];
 Client copyWith({String? fullName,String? phone,String? address,String? customerCode,DateTime? createdDate,List<Interaction>? interactions})=>Client(id:id,fullName:fullName??this.fullName,phone:phone??this.phone,address:address??this.address,customerCode:customerCode??this.customerCode,createdDate:createdDate??this.createdDate,interactions:interactions??this.interactions);
 Map<String,dynamic> toJson()=>{'id':id,'fullName':fullName,'phone':phone,'address':address,'customerCode':customerCode,'createdDate':createdDate.toIso8601String(),'interactions':interactions.map((e)=>e.toJson()).toList()};
 factory Client.fromJson(Map<String,dynamic> j){final raw=j['interactions'];return Client(id:'${j['id']??newId()}',fullName:'${j['fullName']??''}',phone:'${j['phone']??''}',address:'${j['address']??''}',customerCode:'${j['customerCode']??j['Κωδικός Πελάτη']??''}',createdDate:DateTime.tryParse('${j['createdDate']??''}')??DateTime.now(),interactions:raw is List?raw.whereType<Map>().map((e)=>Interaction.fromJson(Map<String,dynamic>.from(e))).toList():[]);}
}

class ClientListScreen extends StatefulWidget { const ClientListScreen({super.key}); @override State<ClientListScreen> createState()=>_ClientListScreenState(); }
class _ClientListScreenState extends State<ClientListScreen> {
 final List<Client> clients=[]; bool loading=true; String query='';
 Future<File> dataFile()async{final d=await getApplicationDocumentsDirectory();return File('${d.path}/ergasies_pelaton.json');}
 Future<void> load()async{try{final f=await dataFile();if(await f.exists()){final x=jsonDecode(await f.readAsString());if(x is List){clients..clear()..addAll(x.whereType<Map>().map((e)=>Client.fromJson(Map<String,dynamic>.from(e))));}}}catch(e){debugPrint('$e');}if(mounted)setState(()=>loading=false);}
 Future<void> save()async{final f=await dataFile();await f.writeAsString(jsonEncode(clients.map((e)=>e.toJson()).toList()),flush:true);}
 @override void initState(){super.initState();load();}
 List<Client> get filtered {final q=norm(query);final out=clients.where((c)=>q.isEmpty||norm('${c.fullName} ${c.phone} ${c.address} ${c.customerCode} ${c.interactions.map((h)=>h.notes).join(' ')}').contains(q)).toList();out.sort((a,b){DateTime latest(Client c)=>c.interactions.isEmpty?c.createdDate:c.interactions.map((h)=>h.date).reduce((x,y)=>x.isAfter(y)?x:y);return latest(b).compareTo(latest(a));});return out;}
 Future<void> upsert(Client c)async{final i=clients.indexWhere((x)=>x.id==c.id);setState((){if(i<0){clients.add(c);}else{clients[i]=c;}});await save();}
 void msg(String s){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));}
 Future<void> editClient([Client? old])async{final n=TextEditingController(text:old?.fullName??''),p=TextEditingController(text:old?.phone??''),a=TextEditingController(text:old?.address??''),code=TextEditingController(text:old?.customerCode??'');await showDialog(context:context,builder:(ctx)=>AlertDialog(title:Text(old==null?'Νέος πελάτης':'Επεξεργασία πελάτη'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Ονοματεπώνυμο')),TextField(controller:code,decoration:const InputDecoration(labelText:'Κωδικός πελάτη (προαιρετικός)')),TextField(controller:p,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Τηλέφωνο')),TextField(controller:a,decoration:const InputDecoration(labelText:'Διεύθυνση'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Άκυρο')),FilledButton(onPressed:()async{if(n.text.trim().isEmpty){msg('Συμπλήρωσε ονοματεπώνυμο.');return;}final cc=code.text.trim();if(cc.isNotEmpty&&clients.any((x)=>x.id!=old?.id&&x.customerCode.toLowerCase()==cc.toLowerCase())){msg('Ο κωδικός χρησιμοποιείται ήδη.');return;}final c=Client(id:old?.id??newId(),fullName:n.text.trim(),phone:p.text.trim(),address:a.text.trim(),customerCode:cc,createdDate:old?.createdDate??DateTime.now(),interactions:old?.interactions??[]);Navigator.pop(ctx);await upsert(c);},child:const Text('Αποθήκευση'))]));n.dispose();p.dispose();a.dispose();code.dispose();}
 Future<void> deleteClient(Client c)async{final yes=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Διαγραφή πελάτη;'),content:Text('Να διαγραφεί ο πελάτης ${c.fullName} και το ιστορικό του;'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Άκυρο')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Διαγραφή'))]));if(yes==true){setState(()=>clients.removeWhere((x)=>x.id==c.id));await save();}}
 Future<void> exportExcel()async{try{final b=Excel.createExcel();b.setDefaultSheet('Clients');final s=b['Clients'];s.appendRow(['ID','Κωδικός Πελάτη','Ονοματεπώνυμο','Τηλέφωνο','Διεύθυνση','Ημερομηνία Δημιουργίας'].map((x)=>TextCellValue(x)).toList());for(final c in clients){s.appendRow([c.id,c.customerCode,c.fullName,c.phone,c.address,dateText(c.createdDate)].map((x)=>TextCellValue(x)).toList());}final h=b['Interactions'];h.appendRow(['Client ID','Πελάτης','Τύπος','Ημερομηνία','Ώρα','Σχόλιο'].map((x)=>TextCellValue(x)).toList());for(final c in clients){for(final i in c.interactions){h.appendRow([c.id,c.fullName,i.type,dateText(i.date),timeText(i.date),i.notes].map((x)=>TextCellValue(x)).toList());}}final bytes=b.save();if(bytes==null)throw Exception('Δεν δημιουργήθηκε αρχείο.');final d=await getTemporaryDirectory(),f=File('${d.path}/ergasies_pelaton.xlsx');await f.writeAsBytes(bytes);await Share.shareXFiles([XFile(f.path)],text:'Εργασίες Πελατών - Excel');}catch(e){msg('Σφάλμα Excel: $e');}}
 Future<void> importExcel()async{try{final pick=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['xlsx','xls']);if(pick==null||pick.files.single.path==null)return;final b=Excel.decodeBytes(await File(pick.files.single.path!).readAsBytes());final incoming=<Client>[];for(final sn in b.tables.keys){final s=b.tables[sn];if(s==null||s.rows.isEmpty)continue;int hr=-1,n=-1,p=-1,a=-1,co=-1,id=-1;for(var r=0;r<s.rows.length;r++){int nn=-1,pp=-1,aa=-1,cc=-1,ii=-1;for(var k=0;k<s.rows[r].length;k++){final h=norm(cell(s.rows[r],k)).replaceAll(RegExp(r'\s+'),' ');if(['ονοματεπωνυμο','ονομα','επωνυμο','πελατης','name','fullname','customer name'].contains(h))nn=k;if(['τηλεφωνο','κινητο','phone','telephone','mobile'].contains(h))pp=k;if(['διευθυνση','address','περιοχη'].contains(h))aa=k;if(['κωδικος πελατη','κωδικος','customer code','customer id'].contains(h))cc=k;if(h=='id'||h=='client id')ii=k;}if(nn>=0){hr=r;n=nn;p=pp;a=aa;co=cc;id=ii;break;}}if(hr<0)continue;final head=s.rows[hr].map((x)=>norm(x?.value?.toString()??'')).toList();if(head.contains('client id')&&(head.contains('τυπος')||head.contains('σχολιο')))continue;for(var r=hr+1;r<s.rows.length;r++){final row=s.rows[r],name=cell(row,n),phone=cell(row,p);if(name.isEmpty)continue;if(clients.any((c)=>c.fullName.toLowerCase()==name.toLowerCase()&&c.phone==phone)||incoming.any((c)=>c.fullName.toLowerCase()==name.toLowerCase()&&c.phone==phone))continue;incoming.add(Client(id:cell(row,id).isEmpty?newId():cell(row,id),fullName:name,phone:phone,address:cell(row,a),customerCode:cell(row,co),createdDate:DateTime.now()));}}if(incoming.isEmpty){msg('Δεν βρέθηκαν νέοι πελάτες. Έλεγξε τις επικεφαλίδες Excel.');return;}setState(()=>clients.addAll(incoming));await save();msg('Εισήχθησαν ${incoming.length} πελάτες.');}catch(e){msg('Σφάλμα εισαγωγής: $e');}}
 Future<void> backup()async{try{final f=await dataFile();await f.writeAsString(jsonEncode(clients.map((e)=>e.toJson()).toList()),flush:true);await Share.shareXFiles([XFile(f.path)],text:'Αντίγραφο ασφαλείας Εργασίες Πελατών');}catch(e){msg('Σφάλμα αντιγράφου: $e');}}
 Future<void> restore()async{try{final p=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json']);if(p==null||p.files.single.path==null)return;final x=jsonDecode(await File(p.files.single.path!).readAsString());if(x is! List)throw const FormatException('Μη έγκυρο αρχείο JSON');final restored=x.whereType<Map>().map((e)=>Client.fromJson(Map<String,dynamic>.from(e))).toList();final yes=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('Επαναφορά;'),content:Text('Θα αντικατασταθούν τα τρέχοντα δεδομένα με ${restored.length} πελάτες.'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Άκυρο')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('Επαναφορά'))]));if(yes==true){setState(()=>clients..clear()..addAll(restored));await save();msg('Η επαναφορά ολοκληρώθηκε.');}}catch(e){msg('Σφάλμα επαναφοράς: $e');}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Εργασίες Πελατών'),actions:[PopupMenuButton<String>(onSelected:(v){if(v=='export')exportExcel();if(v=='import')importExcel();if(v=='backup')backup();if(v=='restore')restore();if(v=='history')Navigator.push(context,MaterialPageRoute(builder:(_)=>HistoryScreen(clients:clients)));if(v=='stats')Navigator.push(context,MaterialPageRoute(builder:(_)=>StatisticsScreen(clients:clients)));},itemBuilder:(_)=>const [PopupMenuItem(value:'export',child:Text('Εξαγωγή Excel')),PopupMenuItem(value:'import',child:Text('Εισαγωγή Excel')),PopupMenuItem(value:'history',child:Text('Όλο το ιστορικό / φίλτρα')),PopupMenuItem(value:'stats',child:Text('Στατιστικά εργασιών')),PopupMenuItem(value:'backup',child:Text('Αντίγραφο ασφαλείας')),PopupMenuItem(value:'restore',child:Text('Επαναφορά αντιγράφου'))])]),body:loading?const Center(child:CircularProgressIndicator()):Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>query=v),decoration:const InputDecoration(labelText:'Αναζήτηση πελάτη, κωδικού ή σχολίου',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))),Expanded(child:filtered.isEmpty?const Center(child:Text('Δεν υπάρχουν πελάτες.')):ListView.builder(itemCount:filtered.length,itemBuilder:(ctx,i){final c=filtered[i];return Card(margin:const EdgeInsets.symmetric(horizontal:12,vertical:5),child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(c.fullName),subtitle:Text('Κωδικός: ${c.customerCode.isEmpty?'Σε αναμονή':c.customerCode}${c.phone.isEmpty?'':'\n${c.phone}'}${c.address.isEmpty?'':'\n${c.address}'}\nΙστορικό: ${c.interactions.length}'),isThreeLine:true,onTap:()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>ClientDetailsScreen(client:c,onChanged:upsert)));setState((){});},trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')editClient(c);if(v=='delete')deleteClient(c);},itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('Επεξεργασία')),PopupMenuItem(value:'delete',child:Text('Διαγραφή'))])));})),]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>editClient(),icon:const Icon(Icons.person_add),label:const Text('Νέος πελάτης')));
}

