class HistoryScreen extends StatefulWidget{final List<Client> clients;const HistoryScreen({super.key,required this.clients});@override State<HistoryScreen> createState()=>_HistoryScreenState();}
class _HistoryScreenState extends State<HistoryScreen>{String q='',type='Όλα';DateTime? from,to;Future<void> pick(bool start)async{final d=await showDatePicker(context:context,initialDate:(start?from:to)??DateTime.now(),firstDate:DateTime(2000),lastDate:DateTime(2100));if(d!=null)setState(()=>start?from=d:to=d);}
@override Widget build(BuildContext context){final rows=<({Client c,Interaction h})>[];for(final c in widget.clients){for(final h in c.interactions){final day=DateTime(h.date.year,h.date.month,h.date.day);if(type!='Όλα'&&h.type!=type)continue;if(q.isNotEmpty&&!norm('${c.fullName} ${c.customerCode} ${h.notes} ${c.phone}').contains(norm(q)))continue;if(from!=null&&day.isBefore(DateTime(from!.year,from!.month,from!.day)))continue;if(to!=null&&day.isAfter(DateTime(to!.year,to!.month,to!.day)))continue;rows.add((c:c,h:h));}}rows.sort((a,b)=>b.h.date.compareTo(a.h.date));return Scaffold(appBar:AppBar(title:const Text('Όλο το ιστορικό')),body:Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(labelText:'Αναζήτηση πελάτη ή σχολίου',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()))),Padding(padding:const EdgeInsets.symmetric(horizontal:12),child:DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Τύπος'),items:const [DropdownMenuItem(value:'Όλα',child:Text('Όλα')),DropdownMenuItem(value:'Τηλεφώνημα',child:Text('Τηλεφωνήματα')),DropdownMenuItem(value:'Επίσκεψη',child:Text('Επισκέψεις'))],onChanged:(v){if(v!=null)setState(()=>type=v);})),Wrap(spacing:6,children:[TextButton(onPressed:()=>pick(true),child:Text(from==null?'Από ημερομηνία':'Από ${dateText(from!)}')),TextButton(onPressed:()=>pick(false),child:Text(to==null?'Έως ημερομηνία':'Έως ${dateText(to!)}')),TextButton(onPressed:()=>setState((){from=null;to=null;type='Όλα';q='';}),child:const Text('Καθαρισμός'))]),Expanded(child:rows.isEmpty?const Center(child:Text('Δεν βρέθηκαν εγγραφές.')):ListView.builder(itemCount:rows.length,itemBuilder:(ctx,i){final r=rows[i];return ListTile(title:Text(r.c.fullName),subtitle:Text('${r.h.type} • ${dateText(r.h.date)} ${timeText(r.h.date)}${r.h.notes.isEmpty?'':'\n${r.h.notes}'}'));}))]));}}
class StatisticsScreen extends StatelessWidget{final List<Client> clients;const StatisticsScreen({super.key,required this.clients});@override Widget build(BuildContext context){final all=clients.expand((c)=>c.interactions).toList(),now=DateTime.now();final month=all.where((h)=>h.date.year==now.year&&h.date.month==now.month).toList();Widget row(String t,int n,IconData i)=>Card(child:ListTile(leading:Icon(i,size:30),title:Text(t),trailing:Text('$n',style:Theme.of(context).textTheme.headlineSmall)));return Scaffold(appBar:AppBar(title:const Text('Στατιστικά εργασιών')),body:ListView(padding:const EdgeInsets.all(12),children:[row('Σύνολο πελατών',clients.length,Icons.people),row('Σύνολο καταχωρίσεων',all.length,Icons.history),row('Τηλεφωνήματα συνολικά',all.where((h)=>h.type=='Τηλεφώνημα').length,Icons.phone),row('Επισκέψεις συνολικά',all.where((h)=>h.type=='Επίσκεψη').length,Icons.location_on),const Divider(),Text('Τρέχων μήνας',style:Theme.of(context).textTheme.titleLarge),row('Τηλεφωνήματα αυτόν τον μήνα',month.where((h)=>h.type=='Τηλεφώνημα').length,Icons.phone_in_talk),row('Επισκέψεις αυτόν τον μήνα',month.where((h)=>h.type=='Επίσκεψη').length,Icons.event),row('Εγγραφές με σχόλια',all.where((h)=>h.notes.trim().isNotEmpty).length,Icons.notes)]));}}
